window.REPORT_PRELOAD_CACHE["NVDA.html"] = {"version":"293f45ea698fd0c86ac011eab9f5bcd81797965de6462fecbd0f110f284c81ea","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>英伟达 NVIDIA (NASDAQ: NVDA) 深度研究报告：从 GPU 加速计算霸主到 AI 工厂与全栈算力基础设施核心引擎</title>\n  <!-- Tailwind CSS -->\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <!-- Chart.js -->\n  <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n  <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n  <script>\n    tailwind.config = {\n      darkMode: 'class',\n      theme: {\n        extend: {\n          fontFamily: {\n            sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n            mono: ['JetBrains Mono', 'monospace'],\n          },\n          colors: {\n            navy: {\n              950: '#070B14',\n              900: '#0F172A',\n              800: '#1E293B',\n              700: '#334155',\n            },\n            nvgreen: {\n              400: '#94D82D',\n              500: '#76B900',\n              600: '#5C9200',\n            },\n            accent: {\n              500: '#3B82F6',\n              600: '#2563EB',\n            },\n            teal: {\n              500: '#06B6D4',\n              600: '#0891B2',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <style>\n    /* 自定义滚动条与机构研报细节排版 */\n    ::-webkit-scrollbar {\n      width: 6px;\n      height: 6px;\n    }\n    ::-webkit-scrollbar-track {\n      background: transparent;\n    }\n    ::-webkit-scrollbar-thumb {\n      background: #94A3B8;\n      border-radius: 3px;\n    }\n    .dark ::-webkit-scrollbar-thumb {\n      background: #475569;\n    }\n\n    /* 打印友好优化 */\n    @media print {\n      #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n        display: none !important;\n      }\n      main {\n        margin-left: 0 !important;\n        padding: 0 !important;\n      }\n      section {\n        break-inside: avoid;\n      }\n    }\n\n    /* 卡片悬浮微光 */\n    .report-card {\n      transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n    }\n    .report-card:hover {\n      transform: translateY(-2px);\n    }\n\n    /* 侧边导航激活态 */\n    .nav-link.active {\n      background: linear-gradient(90deg, rgba(118, 185, 0, 0.22) 0%, rgba(6, 182, 212, 0.06) 100%);\n      border-left: 3px solid #76B900;\n      color: #FFFFFF;\n      font-weight: 600;\n    }\n  </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-nvgreen-500 selection:text-white transition-colors duration-200\">\n\n  <!-- 顶部全局阅读进度条 -->\n  <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n    <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-nvgreen-500 via-emerald-400 to-teal-500 w-0 transition-all duration-150\"></div>\n  </div>\n\n  <!-- 移动端顶部导航栏 -->\n  <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n    <div class=\"flex items-center space-x-2.5\">\n      <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-nvgreen-500 to-nvgreen-600 flex items-center justify-center font-extrabold text-navy-950 shadow\">\n        NV\n      </div>\n      <div>\n        <div class=\"text-[11px] text-nvgreen-400 font-semibold tracking-wider uppercase\">NASDAQ: NVDA · Equity Research</div>\n        <div class=\"text-sm font-bold leading-tight\">英伟达 NVIDIA 深度研究报告</div>\n      </div>\n    </div>\n    <div class=\"flex items-center space-x-2\">\n      <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n        <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n        <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n      </button>\n      <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n        <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <!-- 移动端折叠抽屉菜单 -->\n  <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n    <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n    <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n      <div>\n        <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n          <span class=\"font-bold text-white text-base\">NVDA 研报目录导航</span>\n          <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n          </button>\n        </div>\n        <ul class=\"mt-4 space-y-1.5 text-sm\">\n          <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n          <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与收入架构</a></li>\n          <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重护城河</a></li>\n          <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n          <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值重置</a></li>\n          <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n          <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n        </ul>\n      </div>\n      <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n        <p>全球半导体与 AI 算力基础设施研究组</p>\n        <p class=\"mt-1\">数据基准：2026年11月 (FY26 / FY27E)</p>\n      </div>\n    </nav>\n  </div>\n\n  <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n  <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n    <div>\n      <!-- 机构品牌头 -->\n      <div class=\"p-5 border-b border-slate-800/80\">\n        <div class=\"flex items-center space-x-3\">\n          <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-nvgreen-500 to-nvgreen-600 flex items-center justify-center text-navy-950 font-extrabold text-base shadow-lg shadow-nvgreen-500/25\">\n            NVDA\n          </div>\n          <div>\n            <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-nvgreen-400 bg-nvgreen-500/15 px-2 py-0.5 rounded\">NASDAQ: NVDA</span>\n            <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">英伟达深度研报</h2>\n          </div>\n        </div>\n        <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n          GPU 加速计算霸主 · AI 工厂整机柜与全栈算力基础设施核心引擎\n        </p>\n      </div>\n\n      <!-- 股票实时快照徽章 -->\n      <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">FY26 全年营收</span>\n          <span class=\"font-mono font-bold text-white\">$215.9B <span class=\"text-nvgreen-400\">(+65%)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between\">\n          <span class=\"text-slate-400\">FY27E 营收共识</span>\n          <span class=\"font-mono font-bold text-teal-400\">~$411.0B <span class=\"text-slate-400\">(+90%)</span></span>\n        </div>\n        <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n          <span class=\"text-slate-400\">远期估值锚</span>\n          <span class=\"font-mono font-bold text-nvgreen-400\">~18.0x P/E · PEG 0.18</span>\n        </div>\n      </div>\n\n      <!-- 六个核心章节目录导航 -->\n      <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n        <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n        <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n          <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-nvgreen-400 mr-2\">00</span>执行摘要与核心指标</span>\n          </a>\n          <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与收入架构</span>\n          </a>\n          <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n          </a>\n          <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n          </a>\n          <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n          </a>\n          <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n          </a>\n          <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n            <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n          </a>\n        </nav>\n      </div>\n    </div>\n\n    <!-- 侧边栏底部工具栏 -->\n    <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n      <div class=\"flex items-center justify-between\">\n        <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n        <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n          <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n          <svg class=\"w-3.5 h-3.5 text-nvgreen-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n          <span class=\"dark:hidden\">深色护眼模式</span>\n          <span class=\"hidden dark:inline\">机构亮色模式</span>\n        </button>\n      </div>\n      <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-nvgreen-500 hover:bg-nvgreen-600 text-navy-950 text-xs font-extrabold transition shadow-sm\">\n        <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n        <span>打印 / 导出 PDF 研报</span>\n      </button>\n    </div>\n  </aside>\n\n  <!-- 主内容区 -->\n  <main class=\"lg:ml-[280px] min-h-screen\">\n    <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n      <!-- =========================================================\n           00. Hero 研报封面区与执行摘要\n      ========================================================= -->\n      <section id=\"sec-exec\" class=\"scroll-mt-20\">\n        <!-- 顶部研报元数据标签栏 -->\n        <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n          <div class=\"flex flex-wrap items-center gap-2\">\n            <span class=\"px-2.5 py-1 rounded-md bg-nvgreen-500/15 text-nvgreen-600 dark:text-nvgreen-400 font-bold border border-nvgreen-500/30\">评级：强烈买入 / 核心重仓配置</span>\n            <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：FY2026–FY2027 架构代际跃迁</span>\n          </div>\n          <div class=\"flex items-center space-x-3 font-mono\">\n            <span>覆盖时间：2026年11月</span>\n            <span>NASDAQ: NVDA</span>\n          </div>\n        </div>\n\n        <!-- Hero 标题卡片 -->\n        <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n          <!-- 背景科技绿电路点阵纹理 -->\n          <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#76B900 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n          <div class=\"relative z-10\">\n            <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-nvgreen-500/20 border border-nvgreen-500/40 text-nvgreen-400 text-xs font-semibold mb-4\">\n              <span class=\"w-2 h-2 rounded-full bg-nvgreen-400 animate-pulse\"></span>\n              <span>CORE THESIS · 从单卡卖芯片跃迁至整机柜“AI 工厂” × 18.0x 远期估值安全边际</span>\n            </div>\n            <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n              英伟达 NVIDIA (NASDAQ: NVDA) 深度研究报告：从 GPU 加速计算霸主到 AI 工厂与全栈算力基础设施核心引擎\n            </h1>\n            <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n              英伟达已完成从单一计算芯片供应商向<strong class=\"text-white\">全栈“AI 工厂”系统级基础设施霸主</strong>的跨越。FY2026 全年营收飙升至 <strong class=\"text-nvgreen-400\">$215.9B (+65% YoY)</strong>，其中数据中心贡献 <strong class=\"text-white\">$193.7B（占比 89.7%）</strong>，全年营业现金流高达 <strong class=\"text-teal-400\">$103B</strong>。\n              随着 2026 年 8 月下一代 <strong class=\"text-nvgreen-400\">Vera Rubin</strong> 机柜系统启动量产交付、网络业务突破 <strong class=\"text-white\">$31B</strong> 且主权 AI 暴增超三倍，叠加指数级业绩消化使远期 P/E 回落至 <strong class=\"text-emerald-400\">~18.0x（PEG 仅 0.18）</strong>，配置性价比达到历史罕见高度。\n            </p>\n\n            <!-- 核心投资结论高亮条 -->\n            <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">系统级价值量跃迁</div>\n                <div class=\"text-white font-semibold\">单吉瓦电力对应 NVDA 营收从 Blackwell 的 ~$25B 跃升至 Vera Rubin 的 ~$40B</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">客户结构健康多元化</div>\n                <div class=\"text-nvgreen-400 font-semibold\">主权 AI 暴增超 3 倍突破 $30B，非 CSP 企业与 AI 云客户合计贡献 $70.0B</div>\n              </div>\n              <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n                <div class=\"text-slate-400 font-medium mb-1\">成长消化高估值悖论</div>\n                <div class=\"text-teal-400 font-semibold\">FY27E 营收共识 ~$411B，远期 P/E 仅 ~18.0x（PEG 0.18），远低于 10 年均值 0.93</div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- 4个核心 KPI 卡片 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n          <!-- KPI 1 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>FY2026 全年总营收</span>\n              <span class=\"p-1.5 rounded-lg bg-nvgreen-500/15 text-nvgreen-600 dark:text-nvgreen-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$215.9B</span>\n              <span class=\"text-xs font-bold text-nvgreen-600 dark:text-nvgreen-400 bg-nvgreen-500/15 px-2 py-0.5 rounded\">+65% YoY</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              Blackwell 整机柜大规模放量与网络业务爆发，推动千亿美元体量下仍维持超高速扩张。\n            </p>\n          </div>\n\n          <!-- KPI 2 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>数据中心业务营收</span>\n              <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 12h14M5 12a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2M5 12a2 2 0 00-2 2v4a2 2 0 002 2h14a2 2 0 002-2v-4a2 2 0 00-2-2m-2-4h.01M17 16h.01\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$193.7B</span>\n              <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">占比 89.7%</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              同比增长 +68% YoY；其中网络年营收突破 $31B，GB200/GB300 整机柜占出货约 2/3。\n            </p>\n          </div>\n\n          <!-- KPI 3 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>净利润率 & 营业现金流</span>\n              <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">55.6%</span>\n              <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">OCF $103B</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              FY26 营业利润达 $130B (+60% YoY)，全年股东回报 $41B（Q2 FY27 单季回购分红达 $26B）。\n            </p>\n          </div>\n\n          <!-- KPI 4 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n              <span>FY2027E 预期 & 远期估值</span>\n              <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n                <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n              </span>\n            </div>\n            <div class=\"mt-3 flex items-baseline space-x-2\">\n              <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$411B</span>\n              <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">Fwd P/E ~18.0x</span>\n            </div>\n            <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n              Vera Rubin 放量驱动 FY27E 营收再近翻倍，动态 PEG 仅 0.18，估值性价比显著凸显。\n            </p>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           一、 业务与收入架构 (Business & Revenue Architecture)\n      ========================================================= -->\n      <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-nvgreen-600 dark:text-nvgreen-400\">Section 01 · Business & Revenue Architecture</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：从单卡销售向“AI 工厂整机柜 + 全栈互联”跃迁</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY2026 总营收 $215.9B · 数据中心占比 89.7%</span>\n        </div>\n\n        <!-- 交互式 Chart.js 双视图切换面板 -->\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n          <!-- 左侧：双视图图表 -->\n          <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n              <div>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">FY2022–FY2027E 分部营收演进与数据中心统治力</h3>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">数据中心由 $10.6B 跃升至 FY26 $193.7B，FY27E 向 $380B+ 迈进</p>\n              </div>\n              <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n                <button onclick=\"switchBizChart('evolution')\" id=\"btn-chart-evo\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-nvgreen-600 dark:text-nvgreen-400 shadow-sm transition\">视图A：营收演进</button>\n                <button onclick=\"switchBizChart('dc_split')\" id=\"btn-chart-split\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：数据中心拆解</button>\n              </div>\n            </div>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"bizArchitectureChart\"></canvas>\n            </div>\n          </div>\n\n          <!-- 右侧：结构性拆解核心洞察 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">商业架构三大结构性拐点</h3>\n              <ul class=\"space-y-4 text-sm\">\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-nvgreen-500/15 text-nvgreen-600 dark:text-nvgreen-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">整机柜（Rack-Scale）主导硬件交付</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      Blackwell B200/GB200/GB300 整机柜已占计算出货约 <strong>2/3</strong>，2026年8月下一代 <strong>Vera Rubin</strong> 机柜系统启动量产交付，单机柜集成 GPU、CPU、高速互联与液冷架构。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">网络业务突破 $31B，增速反超计算芯片</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      Mellanox InfiniBand、Spectrum-X 以太网交换机及 NVLink 互联组成全球最大 AI 网络业务，万卡/十万卡集群对无损低延迟互联的刚需驱动网络占比持续扩大。\n                    </p>\n                  </div>\n                </li>\n                <li class=\"flex items-start space-x-3\">\n                  <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n                  <div>\n                    <div class=\"font-semibold text-slate-900 dark:text-white\">非 CSP 客户破 $70B，主权 AI 暴增超三倍</div>\n                    <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                      除大型云巨头（CSP 贡献 $123.8B）外，主权国家 AI 基础设施支出暴增超三倍突破 <strong>$30B</strong>，叠加垂直行业企业与新兴 AI 云，非 CSP 客户合计贡献 <strong>$70.0B</strong>。\n                    </p>\n                  </div>\n                </li>\n              </ul>\n            </div>\n            <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n              <span class=\"text-slate-500 dark:text-slate-400\">核心代际催化剂</span>\n              <span class=\"font-bold text-nvgreen-600 dark:text-nvgreen-400\">Vera Rubin 机柜系统 (2026年8月启动量产)</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- 五大业务分部详细卡片矩阵 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5\">\n          <!-- 分部 1：数据中心 (占两列宽度以突出核心地位) -->\n          <div class=\"md:col-span-2 report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-nvgreen-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n              <div class=\"flex items-center space-x-2\">\n                <span class=\"px-2.5 py-1 rounded-md bg-nvgreen-500/15 text-nvgreen-600 dark:text-nvgreen-400 text-xs font-bold\">绝对核心引擎 · 占比 89.7%</span>\n                <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">+68% YoY</span>\n              </div>\n              <span class=\"text-base font-extrabold font-mono text-slate-900 dark:text-white\">FY26 营收：$193.7B</span>\n            </div>\n            <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 数据中心（Data Center：计算单元 + 高速网络 + 主权 AI）</h3>\n            <div class=\"mt-3 grid grid-cols-1 sm:grid-cols-2 gap-4 text-xs sm:text-sm text-slate-600 dark:text-slate-300\">\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200/70 dark:border-slate-700/70\">\n                <div class=\"font-bold text-slate-900 dark:text-white mb-1\">产品线拆分：计算与网络双轮驱动</div>\n                <p class=\"leading-relaxed\">\n                  计算单元涵盖 Hopper、Blackwell（B200/GB200/GB300 整机柜占出货约 2/3）及 2026 年 8 月启动量产的 <strong>Vera Rubin</strong>；高速互联网络（InfiniBand / Spectrum-X / NVLink）年营收突破 <strong>$31B</strong>，增速快于计算芯片。\n                </p>\n              </div>\n              <div class=\"p-3.5 rounded-xl bg-slate-50 dark:bg-navy-800/60 border border-slate-200/70 dark:border-slate-700/70\">\n                <div class=\"font-bold text-slate-900 dark:text-white mb-1\">客户结构拆分：CSP 稳健 + 主权 AI 爆发</div>\n                <p class=\"leading-relaxed\">\n                  大型云巨头（CSP）贡献 <strong>$123.8B</strong>；而<strong>主权 AI</strong> 业务暴增超三倍突破 <strong>$30B</strong>，叠加专业 AI 云与传统企业级客户，非 CSP 板块合计贡献 <strong>$70.0B</strong>，显著降低单一客户集中度风险。\n                </p>\n              </div>\n            </div>\n          </div>\n\n          <!-- 分部 2：游戏与 AI PC -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">占比 5.3% · +10% YoY</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">$11.4B</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">2. 游戏与 AI PC（Gaming）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                全球独立显卡市占率稳居 <strong>80%–85%</strong>。GeForce RTX 50 Blackwell 系列凭借 DLSS 4 神经网络渲染与本地端侧 AI 算力优势，持续巩固消费级品牌号召力与百万级开发者底盘。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n              独显市占率 80%-85% · 端侧 AI 入口\n            </div>\n          </div>\n\n          <!-- 分部 3：专业可视化 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">占比 0.9% · +21% YoY</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">$1.9B</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">3. 专业可视化（Pro Visualization）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                FY26 Q4 单季营收<strong>加速暴增 159%</strong>。Omniverse 物理 AI 数字孪生平台与 RTX PRO 5000 Blackwell 工作站正成为制造业工厂仿真与企业级 AI 代理（AI Agents）的核心算力载体。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n              Q4 单季增速 +159% · Omniverse 放量\n            </div>\n          </div>\n\n          <!-- 分部 4：汽车与具身智能 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">占比 1.0% · +55% YoY</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">$2.1B</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">4. 汽车与具身智能（Auto & Robotics）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                NVIDIA DRIVE Thor 下一代高算力智驾芯片规模上车，叠加 Jetson Thor 人形机器人计算底座（Project GR00T），手握超 <strong>$140 亿</strong>汽车设计定点管线（Design Win Pipeline）。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold\">\n              定点管线 &gt;$14B · 物理 AI 核心抓手\n            </div>\n          </div>\n\n          <!-- 分部 5：OEM 及其他 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-slate-400 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-3\">\n                <span class=\"px-2.5 py-1 rounded-md bg-slate-500/10 text-slate-600 dark:text-slate-400 text-xs font-bold\">占比 3.1% · +258% YoY</span>\n                <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">$6.8B</span>\n              </div>\n              <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">5. OEM 及其他业务（OEM & Other）</h3>\n              <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n                受惠于边缘 AI 模组、主流游戏主机定制 SoC 放量及授权许可收入激增，FY2026 全年营收实现 <strong>+258%</strong> 爆发式增长，进一步厚实非数据中心板块的现金流贡献。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n              边缘模组与主机芯片 · 同比暴增 258%\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           二、 行业地位与四重核心护城河 (Industry Position & Moat)\n      ========================================================= -->\n      <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：软硬全栈构建深不可测壁垒</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 全球 AI 算力基础设施标准制定者)</span>\n        </div>\n\n        <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n          <!-- 左侧：四重护城河深度解析 -->\n          <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <!-- 护城河 1 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-nvgreen-500/15 text-nvgreen-600 dark:text-nvgreen-400 flex items-center justify-center font-bold text-sm\">01</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">CUDA 生态与 NIM/NeMo 企业护城河</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                近二十年深耕沉淀，汇聚全球<strong>数百万开发者</strong>、数百个垂直领域加速库（cuDNN、TensorRT-LLM）及亿万行底层代码，叠加企业级微服务 <strong>NVIDIA NIM / NeMo</strong>，构筑极高的迁移转换成本与双边网络效应。\n              </p>\n            </div>\n\n            <!-- 护城河 2 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">02</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">全栈系统集成与 NVLink 域互联</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                通过第五/六代 NVLink 与 NVSwitch 将 <strong>72 颗 GPU</strong> 互联为单一超巨型逻辑芯片，商业模式从单卡升级为 GB300 / Vera Rubin 整机柜“AI 工厂”。<strong>单吉瓦（1GW）电力对应 NVDA 营收从 Blackwell 的 ~$25B 跃升至 Vera Rubin 的 ~$40B</strong>。\n              </p>\n            </div>\n\n            <!-- 护城河 3 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">“一年一代”极端敏捷迭代节奏</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                打破半导体传统两年一换代规律，推行 <strong>Hopper → Blackwell → Vera Rubin（集成 Rubin GPU + Vera 独立自研 CPU + Groq 3 LPX 极速推理芯片）</strong>一年一代路线图，令追赶者刚量产即面临 1–2 个代际的能效落后。\n              </p>\n            </div>\n\n            <!-- 护城河 4 -->\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center space-x-2.5 mb-2.5\">\n                <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n                <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">先进封装（CoWoS/HBM）产能锁定霸权</h3>\n              </div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                凭借千亿美元级预付款与全栈BOM掌控力，长期锁定台积电（TSMC）绝大部分 <strong>CoWoS-L 先进封装</strong>产能以及 SK 海力士/美光最高规格 <strong>HBM3e / HBM4</strong> 显存配额，形成物理层面的排他性供给壁垒。\n              </p>\n            </div>\n          </div>\n\n          <!-- 右侧：五维护城河雷达图 -->\n          <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">算力基础设施五维护城河量化雷达图</h3>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">NVIDIA vs AMD/Intel 通用芯片对手 vs 云巨头自研定制 ASIC（满分 10 分）</p>\n            <div class=\"relative h-72 w-full\">\n              <canvas id=\"moatRadarChart\"></canvas>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           三、 同行竞争格局横向对比 (Competitive Landscape)\n      ========================================================= -->\n      <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-nvgreen-600 dark:text-nvgreen-400\">Section 03 · Global Competitive Landscape</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：全栈代际领先，ASIC 仅限局部场景</h2>\n          </div>\n          <!-- 交互式筛选按钮 -->\n          <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n            <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-nvgreen-500 text-navy-950 shadow-sm transition\">全部阵营</button>\n            <button onclick=\"filterCompetitors('merchant')\" data-filter=\"merchant\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">通用算力芯片竞争者</button>\n            <button onclick=\"filterCompetitors('asic')\" data-filter=\"asic\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">云巨头自研定制 ASIC</button>\n            <button onclick=\"filterCompetitors('edge')\" data-filter=\"edge\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">边缘与汽车算力</button>\n          </div>\n        </div>\n\n        <!-- 横向对比矩阵表格 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n          <div class=\"overflow-x-auto\">\n            <table class=\"w-full text-left border-collapse\">\n              <thead>\n                <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n                  <th class=\"py-4 px-5 min-w-[180px]\">竞争厂商与代表架构</th>\n                  <th class=\"py-4 px-4 min-w-[130px]\">软件栈成熟度</th>\n                  <th class=\"py-4 px-4 min-w-[140px]\">互联与机柜扩展</th>\n                  <th class=\"py-4 px-4 min-w-[135px]\">AI 算力市占地位</th>\n                  <th class=\"py-4 px-4 min-w-[115px]\">毛利率水平</th>\n                  <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞合关系评估</th>\n                </tr>\n              </thead>\n              <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n                <!-- 行 1：NVIDIA 基准 -->\n                <tr data-category=\"core\" class=\"bg-nvgreen-500/5 dark:bg-nvgreen-500/10 font-medium\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"flex items-center space-x-2\">\n                      <span class=\"px-2 py-0.5 rounded bg-nvgreen-500 text-navy-950 text-[10px] font-extrabold\">行业标准</span>\n                      <span class=\"font-bold text-slate-900 dark:text-white\">NVIDIA (NVDA)</span>\n                    </div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Blackwell / Vera Rubin / Groq LPX</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">CUDA + NIM 行业绝对标准</span>\n                  </td>\n                  <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">NVLink 72卡域 + IB/Spectrum-X</td>\n                  <td class=\"py-4 px-4 font-bold text-nvgreen-600 dark:text-nvgreen-400\">训练 &gt;90% · 推理主导</td>\n                  <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~73% - 75%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>全栈代际统治者：</strong>唯一提供“芯片+高速互联+整机柜+企业软件”交钥匙 AI 工厂方案，客户 TCO（总拥有成本）最优。\n                  </td>\n                </tr>\n\n                <!-- 行 2：AMD -->\n                <tr data-category=\"merchant\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">AMD (Instinct MI 系列)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">MI325X / MI350 / MI400 机柜</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/15 text-amber-700 dark:text-amber-400\">ROCm 快速追赶 (仍逊于 CUDA)</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">Infinity Fabric + UALink 联盟</td>\n                  <td class=\"py-4 px-4 font-semibold text-slate-700 dark:text-slate-300\">通用 GPU 第二极 (~6%-8%)</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~50% - 54%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>核心追赶者：</strong>凭借大显存容量与性价比成为 CSP 制衡英伟达的首选“第二供应商”，但在超大规模万卡训练稳定性和机柜级生态上仍有代差。\n                  </td>\n                </tr>\n\n                <!-- 行 3：Google TPU -->\n                <tr data-category=\"asic\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Google (TPU v5p / v6 Trillium)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">云巨头内部自研定制 ASIC</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-accent-500/15 text-accent-700 dark:text-accent-400\">JAX / PyTorch XLA (封闭自用)</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">ICI 光电路交换 (OCS 强项)</td>\n                  <td class=\"py-4 px-4 font-semibold text-accent-600 dark:text-accent-400\">自研 ASIC 最强标杆</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">内部自用 (非对外售卖)</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>深度绑定自身生态：</strong>支撑 Gemini 模型训练与推理极具能效优势，但仅限 GCP 内部生态使用，无法对外向企业及主权国家销售，同时仍大量采购 NVDA 满足外部云租户。\n                  </td>\n                </tr>\n\n                <!-- 行 4：Amazon Trainium & Broadcom 定制 ASIC -->\n                <tr data-category=\"asic\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Broadcom / AWS Trainium</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">定制 XPU 设计服务 + 高速交换</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-slate-500/15 text-slate-600 dark:text-slate-400\">Neuron SDK / 高度定制化算子</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">Tomahawk 以太网交换芯片强势</td>\n                  <td class=\"py-4 px-4 font-semibold text-slate-700 dark:text-slate-300\">特定内部推理/训练负载分流</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">AVGO ~65% - 75%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>固定算法负载利器：</strong>在模型结构高度固化的内部推理场景具备单位成本优势，但面对模型架构快速演进（如多模态/Agent）缺乏灵活性，研发周期长。\n                  </td>\n                </tr>\n\n                <!-- 行 5：Intel Gaudi -->\n                <tr data-category=\"merchant\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">Intel (Gaudi 3 / Xeon)</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">传统 x86 巨头转型算力</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-rose-500/10 text-rose-600 dark:text-rose-400\">oneAPI / SynapseAI 生态薄弱</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-600 dark:text-slate-300\">标准以太网 RoCE 互联</td>\n                  <td class=\"py-4 px-4 text-rose-600 dark:text-rose-400 font-semibold\">份额边缘化 (&lt;2%)</td>\n                  <td class=\"py-4 px-4 font-mono text-rose-600 dark:text-rose-400\">~35% - 40%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>战略承压：</strong>受制于代工业务拖累与软件生态割裂，数据中心 AI 加速器商业化进展大幅低于预期。\n                  </td>\n                </tr>\n\n                <!-- 行 6：边缘与汽车算力 (Qualcomm / Mobileye / Tesla FSD) -->\n                <tr data-category=\"edge\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n                  <td class=\"py-4 px-5\">\n                    <div class=\"font-bold text-slate-900 dark:text-white\">高通 / Mobileye / 自研智驾</div>\n                    <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Snapdragon Ride / EyeQ / FSD</div>\n                  </td>\n                  <td class=\"py-4 px-4\">\n                    <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-indigo-500/15 text-indigo-700 dark:text-indigo-400\">端侧车规级编译器与工具链</span>\n                  </td>\n                  <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">单车/单机端侧低功耗 SoC</td>\n                  <td class=\"py-4 px-4 font-semibold text-indigo-600 dark:text-indigo-400\">端侧车规与座舱主力</td>\n                  <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~52% - 56%</td>\n                  <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n                    <strong>端云协同差异化：</strong>高通在智能座舱占优，而英伟达凭借“云端 Cosmos 世界模型训练 + 车端 DRIVE Thor + 机器人 Jetson”全栈闭环在高阶端到端智驾与人形机器人占据制高点。\n                  </td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n\n        <!-- 配套 Chart.js 横向条形图：营业利润率与年度研发投入对比 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球主要算力芯片厂商营业利润率（Operating Margin）与研发壁垒对比</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">NVDA FY26 营业利润率高达 ~60.2%，全年研发投入达 $18.5B（Q2 FY27 单季更飙升至 $7.05B）</p>\n            </div>\n            <span class=\"text-xs font-semibold text-nvgreen-600 dark:text-nvgreen-400 bg-nvgreen-500/15 px-2.5 py-1 rounded\">软件溢价 + 系统集成带来断层盈利能力</span>\n          </div>\n          <div class=\"relative h-60 w-full\">\n            <canvas id=\"compMarginChart\"></canvas>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           四、 财务健康度与估值体系解析 (Financial Health & Valuation)\n      ========================================================= -->\n      <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与估值体系：百亿级现金流与“成长消化估值”悖论</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">远期 P/E ~18.0x · PEG 0.18（远低于10年均值 0.93）</span>\n        </div>\n\n        <!-- 1. 财务健康度四大硬核指标卡 -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-nvgreen-600 dark:text-nvgreen-400 uppercase\">Gross Margin</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">71% – 75%</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              Blackwell 爬坡初期短暂过渡后迅速回升至 73%-75% 稳态高位，体现极强定价权与软件/网络高毛利拉动。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Operating Profit</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$130.0B</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              FY2026 全年营业利润同比大增 +60%，净利润率高达 <strong>55.6%</strong>，经营杠杆效率位居全球万亿市值巨头之首。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Operating Cash Flow</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$103.0B</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              轻晶圆厂（Fabless）模式带来极低资本开支占比，全年经营现金流突破千亿美元大关，现金储备极其充裕。\n            </p>\n          </div>\n\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">Shareholder Return</div>\n            <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">$41.0B / 年</div>\n            <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n              FY2026 全年回购与分红达 $41B；进入 FY27 更进一步加速，Q2 FY27 单季股东回报即高达 <strong>$26.0B</strong>。\n            </p>\n          </div>\n        </div>\n\n        <!-- 2. 交互式 Chart.js 财务与估值演进双轴图 -->\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n            <div>\n              <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY2022–FY2027E 营收/净利润爆发与远期 P/E 估值倍数收敛趋势</h3>\n              <p class=\"text-xs text-slate-500 dark:text-slate-400\">“成长消化高估值”经典范本：盈利呈指数级兑现，使远期 P/E 从 52x 峰值大幅收敛至 ~18.0x</p>\n            </div>\n            <span class=\"text-xs font-mono font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2.5 py-1 rounded\">当前 PEG = 0.18 (10年均值 0.93)</span>\n          </div>\n          <div class=\"relative h-72 w-full\">\n            <canvas id=\"valEvolutionChart\"></canvas>\n          </div>\n        </div>\n\n        <!-- 3. 估值体系演进三阶段 + 华尔街多空分歧面板 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4\">\n          <div class=\"p-5 rounded-xl bg-white dark:bg-navy-900 border border-slate-200 dark:border-slate-800 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"text-xs font-bold text-slate-500\">STAGE 01 · 2022 及以前</span>\n              <span class=\"px-2 py-0.5 rounded bg-slate-100 dark:bg-navy-800 text-[11px] font-mono font-semibold\">20x–30x P/E</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">周期性硬件芯片定价阶段</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              市场将其视为游戏显卡与传统服务器加速卡周期股，估值随 PC 装机量与加密货币库存周期剧烈波动。\n            </p>\n          </div>\n\n          <div class=\"p-5 rounded-xl bg-white dark:bg-navy-900 border border-accent-500/30 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400\">STAGE 02 · 2023–2024</span>\n              <span class=\"px-2 py-0.5 rounded bg-accent-500/15 text-accent-700 dark:text-accent-300 text-[11px] font-mono font-semibold\">50x+ TTM P/E</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">生成式 AI 稀缺性溢价阶段</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              大模型军备竞赛引爆 Hopper 供不应求，市场赋予稀缺垄断溢价，TTM 市盈率一度突破 50x 以上高位。\n            </p>\n          </div>\n\n          <div class=\"p-5 rounded-xl bg-gradient-to-br from-nvgreen-500/10 to-teal-500/10 border border-nvgreen-500/40 shadow-sm\">\n            <div class=\"flex items-center justify-between mb-2\">\n              <span class=\"text-xs font-bold text-nvgreen-600 dark:text-nvgreen-400\">STAGE 03 · 2026 年底当前视角</span>\n              <span class=\"px-2 py-0.5 rounded bg-nvgreen-500/20 text-nvgreen-700 dark:text-nvgreen-300 text-[11px] font-mono font-semibold\">~18.0x Fwd P/E</span>\n            </div>\n            <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">基础设施复利与深度价值安全边际</h4>\n            <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n              随着 FY26 $215.9B 营收与 FY27E ~$411B 共识兑现，远期 P/E 回落至 ~18.0x，PEG 仅 0.18，兼具顶级成长性与深度价值保护。\n            </p>\n          </div>\n        </div>\n\n        <!-- 华尔街多空分歧对比 -->\n        <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n          <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n              <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">万亿订单能见度</span>\n            </div>\n            <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n              <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>2025–2027 累计超 1 万亿美元订单能见度：</strong>Blackwell 与 Vera Rubin 机柜需求排期已锁定至 2027 年下半年。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>Inference-Time Scaling（推理侧扩展定律）：</strong>推理型大模型（Reasoning Models）消耗百倍 Token 算力，带动极速推理芯片需求爆发。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>18.0x 远期 P/E 极具修复空间：</strong>一旦市场确认 FY28 算力支出维持韧性，估值有望向 24x–28x 均值回归。</span></li>\n            </ul>\n          </div>\n\n          <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n            <div class=\"flex items-center justify-between mb-3\">\n              <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n              <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">周期见顶博弈</span>\n            </div>\n            <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>CSP 资本开支增速斜率放缓担忧：</strong>四大云巨头年度 CapEx 基数已极其庞大，市场担忧 2027 年后同比增速边际回落引发“消化期”。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>自研 ASIC 内部替代分流：</strong>Google TPU、AWS Trainium 与微软 Maia 持续优化内部特定推理负载，长期可能限制 GPU 理论天花板。</span></li>\n              <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>电力与物理机房交付瓶颈：</strong>电网并网审批与变压器供应周期可能阶段性制约下游数据中心通电上架速度。</span></li>\n            </ul>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           五、 投资决策与风险配置框架 (Investment Decision & Risk)\n      ========================================================= -->\n      <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-nvgreen-600 dark:text-nvgreen-400\">Section 05 · Investment Decision & Risk Allocation</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景估值推演与风控纪律</h2>\n          </div>\n          <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：全球科技核心底仓 · 紧盯 16x–20x 估值锚点</span>\n        </div>\n\n        <!-- 1. 三情景估值推演卡片 (Bull / Base / Bear) -->\n        <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n          <!-- 牛市情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-nvgreen-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-nvgreen-500/15 text-nvgreen-600 dark:text-nvgreen-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n                <span class=\"font-mono text-xs font-bold text-nvgreen-600 dark:text-nvgreen-400\">概率：30%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标估值：26x – 28x P/E</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>Vera Rubin 机柜放量超预期，主权 AI 与企业级 NIM 软件订阅突破 $100B+，推理型 AI 引发新一轮算力紧缺，毛利率稳守 75% 以上，FY28 营收延续 35%+ 高增。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-nvgreen-600 dark:text-nvgreen-400\">\n              潜在上行空间：+45% 至 +60%（戴维斯双击）\n            </div>\n          </div>\n\n          <!-- 基准情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400 text-xs font-bold\">基准情景 (Base Case)</span>\n                <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">概率：50%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标估值：21x – 23x P/E</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>FY27E 营收如期兑现 ~$411B 共识预期，网络与主权 AI 对冲 CSP 增速换挡，毛利率维持 73%–74%，年度百亿美元股票回购持续增厚 EPS。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n              潜在上行空间：+20% 至 +30%（盈利驱动+温和修复）\n            </div>\n          </div>\n\n          <!-- 熊市情景 -->\n          <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n            <div>\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n                <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n              </div>\n              <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防守估值：14x – 15x P/E</div>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n                <strong>核心假设：</strong>下游 AI 应用商业变现不及预期导致云巨头大幅削减 2027 下半年 CapEx，ASIC 加速替代推理份额，毛利率回落至 68% 左右，市场按传统半导体周期股定价。\n              </p>\n            </div>\n            <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n              潜在下行回撤：-15% 至 -20%（受巨额回购托底）\n            </div>\n          </div>\n        </div>\n\n        <!-- 2. 四大核心风险矩阵 -->\n        <div>\n          <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构对冲缓释策略</h3>\n          <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 下游 CapEx 周期波动风险</span>\n                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">超大规模云厂商资本开支增速放缓与 ROI 验证</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                尽管非 CSP 客户已扩至 $70B，大型云巨头仍贡献超六成数据中心收入。若企业端 AI 软件 ROI 变现滞后，可能触发云厂商阶段性消化库存与放缓下单节奏。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 定制芯片替代分流风险</span>\n                <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：中高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">头部客户自研 ASIC 对推理端份额的蚕食</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                Google TPU、AWS Trainium 等定制 ASIC 在算子固定的内部推理场景具有功耗成本优势，长期可能分流部分标准推理算力需求，需关注专用推理架构（如 LPX）对冲效果。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · 供应链与新架构爬坡风险</span>\n                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">CoWoS / HBM4 瓶颈及 Vera Rubin 机柜良率波动</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                高度集成的整机柜系统涉及数十万个精密组件与液冷散热模块，任何子组件（如光模块、铜缆背板、HBM4 堆叠）良率波动均可能短期影响单季交付确认与毛利率。\n              </p>\n            </div>\n\n            <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n              <div class=\"flex items-center justify-between mb-2\">\n                <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 地缘政治与出口管制风险</span>\n                <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中高</span>\n              </div>\n              <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">跨国算力出口许可与主权合规壁垒</h4>\n              <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n                美国商务部对高端 AI 芯片及主权 AI 算力集群的出口许可审批政策若进一步收紧，可能限制部分海外区域市场拓展并加速本土替代生态培育。\n              </p>\n            </div>\n          </div>\n        </div>\n\n        <!-- 3. 机构级仓位配置建议 -->\n        <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n          <h3 class=\"text-base font-bold text-nvgreen-400 mb-4 flex items-center space-x-2\">\n            <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n            <span>机构级投资组合仓位配置与交易纪律建议</span>\n          </h3>\n          <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-white mb-1\">1. 核心底仓定位（Core Allocation）</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                作为全球 AI 算力基础设施无可替代的“卖水人”与全栈标准制定者，建议在科技与成长型组合中保持<strong>基准权重至超配（Overweight）核心底仓</strong>。\n              </p>\n            </div>\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-nvgreen-400 mb-1\">2. 波段择时锚点（16x–20x Fwd P/E）</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                当前 ~18.0x 远期 P/E（PEG 0.18）处于历史极低分位，具备强回购与高业绩能见度双重护航，建议在 <strong>16x–20x 区间逢宏观情绪波动分批加仓</strong>。\n              </p>\n            </div>\n            <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n              <div class=\"font-bold text-teal-400 mb-1\">3. 产业链上下游配对对冲</div>\n              <p class=\"text-slate-300 leading-relaxed\">\n                可通过适度配置头部光模块/高速铜缆互联、液冷温控及电力设备标的共享机柜密度升级红利，同时以头部云软件应用股对冲单一硬件周期波动。\n              </p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n      ========================================================= -->\n      <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n        <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n          <div>\n            <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n            <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n          </div>\n          <div class=\"flex items-center space-x-2 no-print\">\n            <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-nvgreen-500/15 text-nvgreen-600 dark:text-nvgreen-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n            <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n          </div>\n        </div>\n\n        <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n          <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n            点击勾选机构季报追踪已验证达标的指标（状态自动本地保存），用高频基本面事实动态校准估值安全边际：\n          </p>\n\n          <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n            <!-- KPI 1 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#76B900] focus:ring-nvgreen-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. Vera Rubin 机柜出货爬坡与单吉瓦价值量</span>\n                  <span class=\"text-[11px] font-mono text-nvgreen-600 dark:text-nvgreen-400 font-semibold shrink-0\">核心代际锚</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  跟踪 2026 年 8 月启动量产后的季度出货占比，验证单吉瓦数据中心对应营收是否向 ~$40B 顺利跃升。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 2 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#76B900] focus:ring-nvgreen-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 数据中心网络业务与 Spectrum-X 增速</span>\n                  <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">全栈壁垒指标</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  监测网络分部在突破 $31B 年营收基数后，Spectrum-X 以太网交换机在万卡集群中的渗透率与增速是否持续快于计算卡。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 3 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#76B900] focus:ring-nvgreen-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 主权 AI 与企业级客户占收比是否突破 35%</span>\n                  <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">客户分散度</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  当前非 CSP 客户合计贡献 $70.0B（占数据中心 ~36.1%），持续追踪主权 AI（&gt;$30B）及医疗/金融/制造企业客户扩张广度。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 4 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#76B900] focus:ring-nvgreen-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 综合毛利率是否稳守 73%–75% 黄金区间</span>\n                  <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">定价权晴雨表</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  核查新架构 Rubin 整机柜初期爬坡及 HBM4 采购成本上升背景下，公司通过系统集成与软件溢价稳住 73%–75% 毛利率的能力。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 5 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#76B900] focus:ring-nvgreen-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 头部四大 CSP 季度资本开支（CapEx）指引</span>\n                  <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">先行需求指标</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  跟踪微软、Alphabet、Meta、亚马逊每季财报对 2027 年 AI 数据中心资本开支及电力基建投产的最新上调/维持信号。\n                </p>\n              </div>\n            </label>\n\n            <!-- KPI 6 -->\n            <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n              <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#76B900] focus:ring-nvgreen-500\">\n              <div class=\"flex-1\">\n                <div class=\"flex items-center justify-between gap-2\">\n                  <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 推理端专用算力（LPX）与 NIM 软件变现进展</span>\n                  <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">护城河加固器</span>\n                </div>\n                <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n                  跟踪低延迟极速推理芯片（LPX）商业化落地与 NVIDIA AI Enterprise / NIM 软件订阅年化经常性收入（ARR）扩张进度。\n                </p>\n              </div>\n            </label>\n          </div>\n        </div>\n      </section>\n\n      <!-- =========================================================\n           页脚免责声明 (Disclaimer Footer)\n      ========================================================= -->\n      <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n        <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n          <span>英伟达 NVIDIA (NASDAQ: NVDA) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n          <span>数据基准：FY2026 财报及 2026 年 11 月市场一致预期 (FY27E)</span>\n        </div>\n        <p class=\"leading-relaxed\">\n          <strong>免责声明：</strong>本深度研究报告基于公司公开财务报告、半导体供应链调研及市场一致预期数据整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的 FY2027E 营收预测、单吉瓦价值量测算、三情景估值模型及概率分布均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n        </p>\n      </footer>\n\n    </div>\n  </main>\n\n  <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n  <script>\n    // ==========================================\n    // 1. 亮色 / 深色模式切换（同步刷新所有 Chart.js 图表）\n    // ==========================================\n    function toggleTheme() {\n      const html = document.documentElement;\n      html.classList.toggle('dark');\n      updateChartsTheme();\n    }\n\n    // ==========================================\n    // 2. 移动端抽屉菜单切换\n    // ==========================================\n    function toggleMobileMenu() {\n      const drawer = document.getElementById('mobile-drawer');\n      drawer.classList.toggle('hidden');\n    }\n\n    // ==========================================\n    // 3. 阅读进度条与左侧导航滚动联动高亮\n    // ==========================================\n    const sections = document.querySelectorAll('section[id]');\n    const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n    window.addEventListener('scroll', () => {\n      const scrollTop = window.scrollY;\n      const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n      const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n      document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n      let currentId = 'sec-exec';\n      sections.forEach(sec => {\n        const top = sec.offsetTop - 160;\n        if (scrollTop >= top) {\n          currentId = sec.getAttribute('id');\n        }\n      });\n\n      navLinks.forEach(link => {\n        link.classList.remove('active');\n        const numSpan = link.querySelector('span span');\n        if (numSpan) {\n          numSpan.classList.remove('text-nvgreen-400');\n          numSpan.classList.add('text-slate-500');\n        }\n        if (link.dataset.target === currentId) {\n          link.classList.add('active');\n          if (numSpan) {\n            numSpan.classList.remove('text-slate-500');\n            numSpan.classList.add('text-nvgreen-400');\n          }\n        }\n      });\n    });\n\n    // ==========================================\n    // 4. 同行竞争格局矩阵筛选器\n    // ==========================================\n    function filterCompetitors(category) {\n      document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n        if (btn.dataset.filter === category) {\n          btn.classList.add('bg-nvgreen-500', 'text-navy-950', 'font-semibold', 'shadow-sm');\n          btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        } else {\n          btn.classList.remove('bg-nvgreen-500', 'text-navy-950', 'font-semibold', 'shadow-sm');\n          btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n        }\n      });\n\n      const rows = document.querySelectorAll('#comp-table-body tr');\n      rows.forEach(row => {\n        const rowCat = row.dataset.category;\n        if (category === 'all' || rowCat === 'core' || rowCat === category) {\n          row.style.display = '';\n        } else {\n          row.style.display = 'none';\n        }\n      });\n    }\n\n    // ==========================================\n    // 5. KPI 核查清单状态持久化与计数更新\n    // ==========================================\n    const KPI_STORAGE_KEY = 'nvda_research_kpi_state_v1';\n\n    function loadKpiChecklist() {\n      try {\n        const saved = localStorage.getItem(KPI_STORAGE_KEY);\n        if (saved) {\n          const stateMap = JSON.parse(saved);\n          document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n            if (typeof stateMap[cb.id] === 'boolean') {\n              cb.checked = stateMap[cb.id];\n            }\n          });\n        }\n      } catch (e) {\n        // 忽略存储权限异常\n      }\n      updateKpiChecklist();\n    }\n\n    function updateKpiChecklist() {\n      const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n      const total = checkboxes.length;\n      let checkedCount = 0;\n      const stateMap = {};\n\n      checkboxes.forEach(cb => {\n        stateMap[cb.id] = cb.checked;\n        if (cb.checked) checkedCount++;\n      });\n\n      const pct = Math.round((checkedCount / total) * 100);\n      document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n      try {\n        localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n      } catch (e) {\n        // 忽略存储权限异常\n      }\n    }\n\n    function resetKpiChecklist() {\n      document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n        cb.checked = false;\n      });\n      updateKpiChecklist();\n    }\n\n    // ==========================================\n    // 6. Chart.js 数据可视化初始化与主题自适应\n    // ==========================================\n    let bizChartInstance = null;\n    let radarChartInstance = null;\n    let compMarginChartInstance = null;\n    let valEvolutionChartInstance = null;\n    let currentBizMode = 'evolution';\n\n    function getChartColors() {\n      const isDark = document.documentElement.classList.contains('dark');\n      return {\n        text: isDark ? '#CBD5E1' : '#475569',\n        grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n        radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n      };\n    }\n\n    function initBizChart() {\n      const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n      const colors = getChartColors();\n\n      // 视图 A：FY2022–FY2027E 分部营收演进（堆叠柱状图）\n      const evoConfig = {\n        type: 'bar',\n        data: {\n          labels: ['FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026', 'FY2027E'],\n          datasets: [\n            {\n              label: '数据中心 (Data Center)',\n              data: [10.6, 15.0, 47.5, 115.2, 193.7, 382.0],\n              backgroundColor: '#76B900',\n              borderRadius: 4,\n            },\n            {\n              label: '游戏与 AI PC (Gaming)',\n              data: [12.5, 9.1, 10.4, 10.4, 11.4, 13.0],\n              backgroundColor: '#3B82F6',\n              borderRadius: 4,\n            },\n            {\n              label: '专业可视化 / 汽车 / OEM 其他',\n              data: [3.8, 2.9, 3.0, 4.9, 10.8, 16.0],\n              backgroundColor: '#06B6D4',\n              borderRadius: 4,\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n              }\n            }\n          },\n          scales: {\n            x: {\n              stacked: true,\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              stacked: true,\n              max: 450,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n            }\n          }\n        }\n      };\n\n      // 视图 B：FY2026 数据中心客户结构与产品拆分对比（分组柱状图）\n      const splitConfig = {\n        type: 'bar',\n        data: {\n          labels: [\n            '按客户：大型云巨头 (CSP)',\n            '按客户：AI云与企业客户',\n            '按客户：主权 AI (暴增>3倍)',\n            '按产品：AI 计算单元 (GPU/机柜)',\n            '按产品：高速互联网络 (IB/Spectrum-X)'\n          ],\n          datasets: [\n            {\n              label: 'FY2026 营收贡献 ($B)',\n              data: [123.8, 39.9, 30.0, 162.5, 31.2],\n              backgroundColor: [\n                '#3B82F6',\n                '#06B6D4',\n                '#10B981',\n                '#76B900',\n                '#6366F1'\n              ],\n              borderRadius: 6,\n              barThickness: 26\n            }\n          ]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: { display: false },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `FY26 营收规模: $${ctx.parsed.x}B (占数据中心 ${(ctx.parsed.x / 193.7 * 100).toFixed(1)}%)`\n              }\n            }\n          },\n          scales: {\n            x: {\n              max: 185,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      };\n\n      if (bizChartInstance) bizChartInstance.destroy();\n      bizChartInstance = new Chart(ctx, currentBizMode === 'evolution' ? evoConfig : splitConfig);\n    }\n\n    function switchBizChart(mode) {\n      currentBizMode = mode;\n      const btnEvo = document.getElementById('btn-chart-evo');\n      const btnSplit = document.getElementById('btn-chart-split');\n      const titleEl = document.getElementById('biz-chart-title');\n      const subEl = document.getElementById('biz-chart-sub');\n\n      if (mode === 'evolution') {\n        btnEvo.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-nvgreen-600 dark:text-nvgreen-400 shadow-sm transition';\n        btnSplit.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = 'FY2022–FY2027E 分部营收演进与数据中心统治力';\n        subEl.textContent = '数据中心由 $10.6B 跃升至 FY26 $193.7B，FY27E 向 $380B+ 迈进';\n      } else {\n        btnSplit.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-nvgreen-600 dark:text-nvgreen-400 shadow-sm transition';\n        btnEvo.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n        titleEl.textContent = 'FY2026 数据中心（$193.7B）客户结构与产品拆分';\n        subEl.textContent = '非 CSP 客户合计达 $70.0B（主权 AI 破 $30B），网络业务突破 $31B';\n      }\n      initBizChart();\n    }\n\n    function initRadarChart() {\n      const ctx = document.getElementById('moatRadarChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (radarChartInstance) radarChartInstance.destroy();\n      radarChartInstance = new Chart(ctx, {\n        type: 'radar',\n        data: {\n          labels: [\n            '软件生态锁定 (CUDA/NIM)',\n            '整机柜互联与带宽 (NVLink)',\n            '单瓦算力与一年一代节奏',\n            '供应链 CoWoS/HBM 议价',\n            '长期客户黏性与平台迁移成本'\n          ],\n          datasets: [\n            {\n              label: 'NVIDIA (NVDA)',\n              data: [9.9, 9.8, 9.7, 9.8, 9.6],\n              borderColor: '#76B900',\n              backgroundColor: 'rgba(118, 185, 0, 0.22)',\n              pointBackgroundColor: '#76B900',\n              borderWidth: 2.5\n            },\n            {\n              label: '云巨头自研定制 ASIC (TPU/Trainium)',\n              data: [6.2, 7.6, 7.4, 7.2, 8.0],\n              borderColor: '#3B82F6',\n              backgroundColor: 'rgba(59, 130, 246, 0.14)',\n              pointBackgroundColor: '#3B82F6',\n              borderWidth: 1.8\n            },\n            {\n              label: 'AMD / Intel 通用算力对手',\n              data: [5.8, 6.4, 7.0, 6.5, 5.5],\n              borderColor: '#94A3B8',\n              backgroundColor: 'rgba(148, 163, 184, 0.12)',\n              pointBackgroundColor: '#94A3B8',\n              borderWidth: 1.5,\n              borderDash: [4, 4]\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n            }\n          },\n          scales: {\n            r: {\n              min: 0,\n              max: 10,\n              ticks: { display: false, stepSize: 2 },\n              grid: { color: colors.grid },\n              angleLines: { color: colors.radarAngle },\n              pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initCompMarginChart() {\n      const ctx = document.getElementById('compMarginChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (compMarginChartInstance) compMarginChartInstance.destroy();\n      compMarginChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: [\n            'NVIDIA (NVDA · 全栈 AI 工厂)',\n            'Broadcom (AVGO · 定制 ASIC 与网络)',\n            'Qualcomm (QCOM · 端侧与汽车算力)',\n            'AMD (Instinct MI + 传统 CPU)',\n            'Intel (INTC · 代工拖累转型期)'\n          ],\n          datasets: [{\n            label: '营业利润率 Operating Margin (%)',\n            data: [60.2, 42.5, 28.4, 16.5, 4.2],\n            backgroundColor: [\n              '#76B900',\n              '#3B82F6',\n              '#06B6D4',\n              '#64748B',\n              '#94A3B8'\n            ],\n            borderRadius: 6,\n            barThickness: 22\n          }]\n        },\n        options: {\n          indexAxis: 'y',\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: { display: false },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => `营业利润率: ${ctx.parsed.x}%`\n              }\n            }\n          },\n          scales: {\n            x: {\n              max: 70,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n            },\n            y: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            }\n          }\n        }\n      });\n    }\n\n    function initValEvolutionChart() {\n      const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n      const colors = getChartColors();\n\n      if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n      valEvolutionChartInstance = new Chart(ctx, {\n        type: 'bar',\n        data: {\n          labels: ['FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026', 'FY2027E'],\n          datasets: [\n            {\n              type: 'bar',\n              label: '全年总营收 ($B)',\n              data: [26.9, 27.0, 60.9, 130.5, 215.9, 411.0],\n              backgroundColor: 'rgba(118, 185, 0, 0.85)',\n              borderRadius: 5,\n              barThickness: 24,\n              yAxisID: 'y'\n            },\n            {\n              type: 'bar',\n              label: '全年净利润 ($B)',\n              data: [9.8, 4.4, 29.8, 72.9, 120.0, 228.0],\n              backgroundColor: 'rgba(59, 130, 246, 0.85)',\n              borderRadius: 5,\n              barThickness: 24,\n              yAxisID: 'y'\n            },\n            {\n              type: 'line',\n              label: '远期市盈率 Forward P/E (x)',\n              data: [38.0, 52.0, 36.5, 29.0, 22.5, 18.0],\n              borderColor: '#F59E0B',\n              backgroundColor: '#F59E0B',\n              borderWidth: 3,\n              pointRadius: 5,\n              pointHoverRadius: 7,\n              tension: 0.25,\n              yAxisID: 'y1'\n            }\n          ]\n        },\n        options: {\n          responsive: true,\n          maintainAspectRatio: false,\n          plugins: {\n            legend: {\n              position: 'bottom',\n              labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n            },\n            tooltip: {\n              callbacks: {\n                label: (ctx) => ctx.dataset.yAxisID === 'y'\n                  ? `${ctx.dataset.label}: $${ctx.parsed.y}B`\n                  : `${ctx.dataset.label}: ${ctx.parsed.y}x`\n              }\n            }\n          },\n          scales: {\n            x: {\n              grid: { display: false },\n              ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n            },\n            y: {\n              type: 'linear',\n              position: 'left',\n              max: 450,\n              grid: { color: colors.grid },\n              ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n            },\n            y1: {\n              type: 'linear',\n              position: 'right',\n              min: 0,\n              max: 60,\n              grid: { drawOnChartArea: false },\n              ticks: { color: '#F59E0B', font: { size: 11, weight: '600' }, callback: v => v + 'x' }\n            }\n          }\n        }\n      });\n    }\n\n    function updateChartsTheme() {\n      initBizChart();\n      initRadarChart();\n      initCompMarginChart();\n      initValEvolutionChart();\n    }\n\n    window.addEventListener('DOMContentLoaded', () => {\n      loadKpiChecklist();\n      initBizChart();\n      initRadarChart();\n      initCompMarginChart();\n      initValEvolutionChart();\n    });\n  </script>\n</body>\n</html>"};
